import minimist from 'minimist';
import fs from 'fs';
import path from 'path';
import OpenAI from 'openai';
import { AlchemystAI } from '@alchemystai/sdk';

const RUN_ID_PATH = '/logs/artifacts/run-id';
const OUTPUT_DIR = '/home/user/myproject/output';
const OUTPUT_PATH = path.join(OUTPUT_DIR, 'newsletter.md');

interface Article {
  file_name: string;
  content: string;
}

function getRunId(): string {
  try {
    const runId = fs.readFileSync(RUN_ID_PATH, 'utf8').trim();
    if (!runId) {
      throw new Error('run-id is empty');
    }
    return runId;
  } catch (err: any) {
    throw new Error(`Failed to read run-id from ${RUN_ID_PATH}: ${err.message}`);
  }
}

function buildArticles(runId: string): Article[] {
  return [
    {
      file_name: `b2b_article_ai_agents_${runId}.md`,
      content:
        'AI agents are REDACTEDnomous software systems built on top of large language models (LLMs). They plan multi-step workflows, call external tools, and reflect on their own outputs. Modern agentic systems combine planning, tool use, memory, and orchestration to REDACTEDmate knowledge work. Keywords: REDACTEDnomous, agentic, planning, tool use, orchestration.',
    },
    {
      file_name: `b2b_article_rag_${runId}.md`,
      content:
        'Retrieval-Augmented Generation (RAG) augments LLM prompts with snippets retrieved from a vector store. Documents are chunked, embedded, and indexed; at query time a semantic search returns the most relevant chunks and the LLM grounds its answer in that retrieved context.',
    },
    {
      file_name: `b2b_article_vector_db_${runId}.md`,
      content:
        'Vector databases such as Pinecone, Weaviate, and pgvector store high-dimensional embeddings and support approximate nearest neighbor search. They power semantic retrieval over unstructured text, images, and code by mapping content into a shared embedding space.',
    },
    {
      file_name: `b2b_article_prompt_engineering_${runId}.md`,
      content:
        'Prompt engineering is the practice of designing effective instructions for large language models. Common techniques include few-shot examples, chain-of-thought reasoning, role prompts, and structured output formats such as JSON. Good prompts reduce hallucinations and improve task performance.',
    },
    {
      file_name: `b2b_article_devops_${runId}.md`,
      content:
        'DevOps practices accelerate software delivery through continuous integration, continuous deployment, infrastructure-as-code, and observability. Tools such as Kubernetes, Terraform, and GitHub Actions REDACTEDmate provisioning, deployment, and monitoring of production systems.',
    },
  ];
}

async function seedArticles(client: AlchemystAI, articles: Article[]): Promise<void> {
  const documents = articles.map((a) => ({
    content: a.content,
    metadata: {
      file_name: a.file_name,
      context_type: 'resource',
      scope: 'internal',
    },
  }));
  // The SDK exposes v1.context.add. It is safe to call repeatedly as long as
  // file_name values are unique per run (we namespace with run-id).
  // Use a no-similarity-grouping strategy so we don't require an existing group.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (client as any).v1.context.add({
    documents,
    context_type: 'resource',
    scope: 'internal',
  });
}

async function searchContext(client: AlchemystAI, topic: string): Promise<{ content: string }[]> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const result: any = await (client as any).v1.context.search({
    query: topic,
    context_type: 'resource',
    scope: 'internal',
    // Retrieve enough snippets to ground the newsletter
    top_k: 5,
  });

  // The SDK may return either { contexts: [...] } or { data: [...] } depending on version.
  const contexts: any[] =
    (Array.isArray(result?.contexts) && result.contexts) ||
    (Array.isArray(result?.data) && result.data) ||
    (Array.isArray(result?.results) && result.results) ||
    (Array.isArray(result) && result) ||
    [];

  return contexts.map((c: any) => ({ content: String(c.content ?? c.text ?? '') }));
}

async function generateNewsletter(topic: string, grounding: string): Promise<string> {
  const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

  const systemPrompt =
    'You are a B2B newsletter writer. Produce concise, professional newsletters grounded in the supplied research context. Always output valid Markdown.';

  const userPrompt = `Write a short B2B newsletter on the topic: "${topic}".

Use only the following research context as factual grounding. Do not invent facts beyond what is provided.

=== RESEARCH CONTEXT ===
${grounding}
=== END CONTEXT ===

Requirements:
- Output MUST be valid Markdown.
- The newsletter MUST contain at least three sections, each introduced by a Markdown heading line (starting with #, ##, or ###).
- Include at least these three sections (you may add more):
  ## Why it matters
  ## What\'s new
  ## What to do next
- Keep it concise (roughly 250-500 words total).
- Address a B2B audience (decision-makers, engineering leaders).
- Reference concrete details drawn from the research context.`;

  const completion = await openai.chat.completions.create({
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt },
    ],
    temperature: 0.7,
  });

  const text = completion.choices?.[0]?.message?.content ?? '';
  return text;
}

async function main(): Promise<void> {
  const argv = minimist(process.argv.slice(2));
  const topic = argv.topic || argv.t;
  if (!topic || typeof topic !== 'string') {
    console.error('Usage: node dist/main.js --topic "<topic>"');
    process.exit(1);
  }

  const alchemystKey = process.env.ALCHEMYST_AI_API_KEY;
  const openaiKey = process.env.OPENAI_API_KEY;
  if (!alchemystKey) {
    console.error('Missing ALCHEMYST_AI_API_KEY environment variable.');
    process.exit(1);
  }
  if (!openaiKey) {
    console.error('Missing OPENAI_API_KEY environment variable.');
    process.exit(1);
  }

  const runId = getRunId();
  console.log(`[newsletter] Using run-id: ${runId}`);
  console.log(`[newsletter] Topic: ${topic}`);

  const alchemyst = new AlchemystAI({ apiKey: alchemystKey });

  // 1) Seed articles
  const articles = buildArticles(runId);
  console.log(`[newsletter] Seeding ${articles.length} articles into context engine...`);
  try {
    await seedArticles(alchemyst, articles);
    console.log('[newsletter] Seeding complete.');
  } catch (err: any) {
    console.error(`[newsletter] Failed to seed articles: ${err.message}`);
    throw err;
  }

  // 2) Search context
  console.log('[newsletter] Searching context engine...');
  const contexts = await searchContext(alchemyst, topic);
  console.log(`[newsletter] Retrieved ${contexts.length} context snippet(s).`);

  const grounding = contexts.map((c) => c.content).join('\n\n');
  if (!grounding.trim()) {
    console.warn('[newsletter] Warning: no grounding context was retrieved; continuing anyway.');
  }

  // 3) Generate newsletter
  console.log('[newsletter] Generating newsletter with OpenAI...');
  const newsletter = await generateNewsletter(topic, grounding);
  if (!newsletter.trim()) {
    throw new Error('OpenAI returned empty content.');
  }

  // 4) Persist
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, newsletter, 'utf8');
  console.log(`[newsletter] Wrote newsletter to ${OUTPUT_PATH}`);
}

main().catch((err) => {
  console.error('[newsletter] Fatal error:', err);
  process.exit(1);
});
